DROP TABLE IF EXISTS `inventory_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_item` (
  `inventory_item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '统一库存物品ID',
  `item_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '来源类型：MATERIAL/PRODUCT',
  `source_id` bigint NOT NULL COMMENT '来源档案ID：material_id/product_id',
  `item_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存物品编码',
  `item_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '库存物品名称',
  `specification` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规格型号',
  `unit` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'PCS' COMMENT '库存单位',
  `batch_managed` tinyint NOT NULL DEFAULT '1' COMMENT '是否批次管理',
  `location_managed` tinyint NOT NULL DEFAULT '1' COMMENT '是否库位管理',
  `safe_stock` decimal(12,4) NOT NULL DEFAULT '0.0000' COMMENT '安全库存',
  `max_stock` decimal(12,4) DEFAULT NULL COMMENT '最高库存',
  `reorder_point` decimal(12,4) DEFAULT NULL COMMENT '再订货点',
  `default_warehouse_id` bigint DEFAULT NULL COMMENT '默认仓库',
  `default_location_id` bigint DEFAULT NULL COMMENT '默认库位',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '启用状态',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`inventory_item_id`),
  UNIQUE KEY `uk_inventory_item_source` (`item_type`,`source_id`),
  UNIQUE KEY `uk_inventory_item_code` (`item_code`),
  KEY `idx_inventory_item_type_status` (`item_type`,`status`),
  KEY `fk_inventory_item_warehouse` (`default_warehouse_id`),
  KEY `fk_inventory_item_location` (`default_location_id`),
  CONSTRAINT `fk_inventory_item_location` FOREIGN KEY (`default_location_id`) REFERENCES `inventory_storage_location` (`location_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_inventory_item_warehouse` FOREIGN KEY (`default_warehouse_id`) REFERENCES `inventory_warehouse` (`warehouse_id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2084 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一库存物品主数据';
